() => { 
  // Try to close any modal/dialog
  const closeButtons = document.querySelectorAll('[aria-label*="关闭"], [aria-label*="Close"], button');
  for (const btn of closeButtons) {
    if (btn.textContent.includes('关闭') || btn.getAttribute('aria-label')?.includes('Close') || btn.getAttribute('aria-label')?.includes('close')) {
      btn.click();
      return 'clicked close button: ' + btn.textContent;
    }
  }
  // Press escape
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }));
  return 'pressed escape';
}

() => {
  // Press Escape on the document
  const evt = new KeyboardEvent('keydown', { key: 'Escape', bubbles: true, cancelable: true });
  document.dispatchEvent(evt);
  // Try clicking on empty area
  const map = document.querySelector('[role="main"]');
  return 'attempted escape, body classes: ' + document.body.className;
}
